 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    # Uniform full rows/columns are the colored partition lines.
    sep_rows = {r for r in range(h) if len(set(grid[r])) == 1}
    sep_cols = {c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1}
    sep_colors = [grid[r][0] for r in sep_rows] + [grid[0][c] for c in sep_cols]
    sep_color = Counter(sep_colors).most_common(1)[0][0]
    sep_rows = {r for r in sep_rows if grid[r][0] == sep_color}
    sep_cols = {c for c in sep_cols if grid[0][c] == sep_color}

    def segments(length, separators):
        out = []
        start = 0
        for i in sorted(separators):
            if start < i:
                out.append((start, i))
            start = i + 1
        if start < length:
            out.append((start, length))
        return out

    row_blocks = segments(h, sep_rows)
    col_blocks = segments(w, sep_cols)
    bg_counts = Counter(grid[r][c] for r in range(h) for c in range(w)
                        if r not in sep_rows and c not in sep_cols)
    background = bg_counts.most_common(1)[0][0]

    blocks = [(rs, cs) for rs in row_blocks for cs in col_blocks]
    def score(block):
        (r0, r1), (c0, c1) = block
        return sum(grid[r][c] != background
                   for r in range(r0, r1) for c in range(c0, c1))

    source = max(blocks, key=score)
    (sr0, sr1), (sc0, sc1) = source
    tile = [row[sc0:sc1] for row in grid[sr0:sr1]]
    out = [row[:] for row in grid]
    for (r0, r1), (c0, c1) in blocks:
        if (r0, r1, c0, c1) == (sr0, sr1, sc0, sc1):
            continue
        if r1 - r0 == len(tile) and c1 - c0 == len(tile[0]):
            for dr in range(len(tile)):
                out[r0 + dr][c0:c1] = tile[dr][:]
    return out
